#a example generated python ANSI script.
#!/usr/bin/env python3
# -*- coding: utf-8 -*-

import time
import sys
import os
import gzip
import base64
import json

FPS = 30 #you can change this
FRAME_DELAY = 1.0 / FPS

#compressed frames to Base64
DATA = ""

def load_frames():
    raw_gzip = base64.b64decode(DATA)
    json_bytes = gzip.decompress(raw_gzip)
    return json.loads(json_bytes.decode('utf-8'))

def main():
    if sys.platform == "win32":
        os.system('')
    
    sys.stdout.write("loading frames...\r")
    sys.stdout.flush()
    frames = load_frames()

    #clearing screen
    sys.stdout.write("\033[2J\033[H\033[?25l")
    sys.stdout.flush()

    try:
        while True:
            for frame in frames:
                t0 = time.time()
                output = "\033[H\033[0J" + "\n".join(frame) + "\033[0m\n"
                sys.stdout.write(output)
                sys.stdout.flush()
                
                delta = time.time() - t0
                time.sleep(max(0.0, FRAME_DELAY - delta))
    except KeyboardInterrupt:
        sys.stdout.write("\033[?25h\033[0m\n")
        sys.stdout.flush()
        print("Stopped.")

if __name__ == "__main__":
    main()
